solution.solution.cpp:
#include <string>
#include <tuple>
#include <variant>
#include <vector>

struct Circle { double radius{}; };
struct Rectangle { double width{}; double height{}; };
struct Triangle { double base{}; double height{}; };

using Shape = std::variant<Circle, Rectangle, Triangle>;

template <typename... Fs>
struct Overloaded : Fs... { using Fs::operator()...; };

double area(const Shape& shape)
{
    return std::visit(Overloaded{
        [](const Circle& c) { return 3.14159 * c.radius * c.radius; },
        [](const Rectangle& r) { return r.width * r.height; },
        [](const Triangle& t) { return t.base * t.height / 2.0; },
    }, shape);
}

std::string name(const Shape& shape)
{
    return std::visit(Overloaded{
        [](const Circle&) { return std::string{ "circle" }; },
        [](const Rectangle&) { return std::string{ "rectangle" }; },
        [](const Triangle&) { return std::string{ "triangle" }; },
    }, shape);
}

std::tuple<std::string, double> largest(const std::vector<Shape>& shapes)
{
    std::tuple<std::string, double> best{ "none", 0.0 };
    bool any{ false };
    for (const Shape& shape : shapes)
    {
        const double a{ area(shape) };
        if (!any || a > std::get<1>(best))
        {
            best = { name(shape), a };
            any = true;
        }
    }
    return best;
}

unitTests:
TEST("area") { CHECK_NEAR(area(Circle{ 1.0 }), 3.14159, 1e-9); CHECK_NEAR(area(Rectangle{ 3, 4 }), 12.0, 1e-9); CHECK_NEAR(area(Triangle{ 4, 5 }), 10.0, 1e-9); }
TEST("name") { CHECK_EQ(name(Circle{}), "circle"); CHECK_EQ(name(Rectangle{}), "rectangle"); CHECK_EQ(name(Triangle{}), "triangle"); }
TEST("largest, unpacked with structured bindings") { const auto [n, a]{ largest({ Circle{ 1.0 }, Rectangle{ 3, 4 }, Triangle{ 4, 5 } }) }; CHECK_EQ(n, "rectangle"); CHECK_NEAR(a, 12.0, 1e-9); }
TEST("empty list") { const auto [n, a]{ largest({}) }; CHECK_EQ(n, "none"); CHECK_NEAR(a, 0.0, 1e-12); }

